// 这个是路由的文件
import Vue from 'vue'
import Router from 'vue-router'
import Home from '@/components/Home'
import User from '@/components/User'
import Button from '@/components/Button'
import Transfer from '@/components/Transfer'
import InputNumber from '@/components/InputNumber'
import jiemi from '@/components/jiemi'
import recently from '@/components/recently'
import secrets from '@/components/secrets'
import yinxie from '@/components/yinxie'
Vue.use(Router)

export default new Router({
  routes: [
    {
      path: '/',    // 表示当根目录的组件使用router-view标签进行访问的时候，就在访问处展示HelloWorld这个component
      redirect: '/home'
    },
    {
      path: '/secrets',    // 表示当根目录的组件使用router-view标签进行访问的时候，就在访问处展示HelloWorld这个component
      component: secrets
    },
    {
      path: '/yinxie',    // 表示当根目录的组件使用router-view标签进行访问的时候，就在访问处展示HelloWorld这个component
      component: yinxie
    },
    {
      path: '/jiemi',    // 表示当根目录的组件使用router-view标签进行访问的时候，就在访问处展示HelloWorld这个component
      component: jiemi
    },
    {
      path: '/button',    // 表示当根目录的组件使用router-view标签进行访问的时候，就在访问处展示HelloWorld这个component
      component: Button
    },
    {
      path: '/recently',    // 表示当根目录的组件使用router-view标签进行访问的时候，就在访问处展示HelloWorld这个component
      component: recently
    },
    {
      path: '/inputnumber',    // 表示当根目录的组件使用router-view标签进行访问的时候，就在访问处展示HelloWorld这个component
      component: InputNumber
    },
    {
      path: '/transfer',    // 表示当根目录的组件使用router-view标签进行访问的时候，就在访问处展示HelloWorld这个component
      component: Transfer
    },
    {
      path: '/home',    // 表示当根目录的组件使用router-view标签进行访问的时候，就在访问处展示HelloWorld这个component
      name: 'Home',
      component: Home
    },
    {
      path: '/user',    // 表示当访问/User时，就展示User这个component
      name: 'User',
      component: User
    }
  ]
})



