<template>
  <div>
    <h1>用户模块</h1>
    <a href="#/">回到主页</a>
    <el-button type="primary" icon="el-icon-edit">编辑</el-button>
    <table border="1">
      <tr>
        <td>id</td>
        <td>name</td>
        <td>age</td>
        <td>操作</td>
      </tr>
      <tr v-for="user in users" :key="user">
        <td>{{ user.id }}</td>
        <td>{{ user.name }}</td>
        <td>{{ user.age }}</td>
        <td><a href="">删除</a> <a href="">修改</a></td>
      </tr>
    </table>

    <Footer></Footer>
  </div>
</template>

<script>
import Footer from "./Footer.vue";
export default {
  data() {
    return {
      users: [
        { id: 1, name: "Tom", age: 18 },
        { id: 2, name: "jack", age: 19 },
        { id: 3, name: "rose", age: 17 },
      ],
    };
  },
  components: {
    Footer,
  },
};
</script>

<style>
table {
  margin-right: auto;
  margin-left: auto;
}
</style>


